    "llmset.color_title": "Vehicle color correction (vision)",
    "llmset.color_desc": "The current color classifier has a measured bias (confuses gray/silver and blue). The vision model rechecks recent readings and corrects them — periodic task + manual button. Automatically skips monochrome IR (night) images — no reliable color to extract from them.",
